def row_chances(text, word):
    words = text.split()
    nexts = []
    counts = []
    for i in range(len(words) - 1):
        if words[i] == word:
            b = words[i + 1]
            if b in nexts:
                counts[nexts.index(b)] += 1
            else:
                nexts.append(b)
                counts.append(1)
    total = 0
    for c in counts:
        total = total + c
    result = []
    for k in range(len(nexts)):
        result.append((nexts[k], counts[k], total))
    return result

